"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["69602"],{94255(e){e.exports=JSON.parse('{"id":"FIN-1137","slug":"modified-internal-rate-of-return","term":"Modified Internal Rate of Return (MIRR)","also_known_as":["MIRR"],"difficulty":"Advanced","definition":"The modified internal rate of return (MIRR) is a version of the internal rate of return that assumes cash flows from a project are reinvested at a chosen rate, usually the cost of capital, rather than at the project\'s own internal rate of return.","explanation":["The standard internal rate of return implicitly assumes that cash produced by a project can be reinvested at the same rate as the project itself. For very profitable projects, this can overstate the true return. MIRR fixes this by using a more realistic reinvestment rate.","To calculate MIRR, positive cash flows are compounded forward to the end of the project at the reinvestment rate, negative cash flows are discounted to the start at the financing rate, and MIRR is the rate that links the two.","For example, a project costs 1,000 and returns 600 at the end of each of the next two years. Its IRR is about 13.1%. If cash can be reinvested at 8%, the first 600 grows to 648 by the end of year two, giving a total of 1,248. The MIRR is about 11.7%.","MIRR also avoids the problem of projects with unusual cash flows having more than one IRR. It is usually considered alongside net present value, which remains the most reliable measure of value."],"note":"","total":1725,"prev":{"slug":"modified-duration","term":"Modified Duration"},"next":{"slug":"modigliani-miller-theorem","term":"Modigliani-Miller Theorem"}}')}}]);